// Build one item per (event x status) for the CURRENT month, using the REAL GHL tag
// format discovered in live data:  event-{event}-{YYYY-MM}-{status}
const EVENTS = ['mastermind', 'venture-vitality', 'pitch-to-yes'];
const STATUSES = ['registered', 'accepted', 'attended'];
const now = new Date();
const month = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0');
const out = [];
for (const event of EVENTS) {
  for (const status of STATUSES) {
    out.push({ json: { event, month, status, tag: `event-${event}-${month}-${status}` } });
  }
}
return out;

// Zip Define Event x Status items with their GHL counts (same order),
// group into one row per event with registered/accepted/attended totals.
const defs = $('Define Event×Status').all();
const res = $input.all();
const byEvent = {};
for (let i = 0; i < defs.length; i++) {
  const dd = defs[i].json;
  const body = (res[i] && res[i].json) || {};
  const total = Number(body.total ?? (body.meta && body.meta.total) ?? 0);
  const key = dd.month + '|' + dd.event;
  if (!byEvent[key]) byEvent[key] = { 'Event': dd.event, 'Month': dd.month, 'Registered': 0, 'Accepted': 0, 'Attended': 0, 'Snapshot Key': key };
  if (dd.status === 'registered') byEvent[key]['Registered'] = total;
  if (dd.status === 'accepted')  byEvent[key]['Accepted']  = total;
  if (dd.status === 'attended')  byEvent[key]['Attended']  = total;
}
return Object.values(byEvent).map(json => ({ json }));
